// @ts-check
/**
 * @file Regenerates src/client/public-suffix.mjs from the Public Suffix List.
 *
 * Run by hand (it needs the network): `node scripts/update-psl.mjs`, or
 * `node scripts/update-psl.mjs path/to/public_suffix_list.dat` for a copy
 * already downloaded. Review the diff, then run `npm run check`. The build
 * warns when the copy is more than six months old.
 *
 * The list is published by Mozilla under the MPL 2.0; the generated file
 * keeps that licence (see REUSE.toml) and its notice.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const SOURCE = 'https://publicsuffix.org/list/public_suffix_list.dat';
const OUT = fileURLToPath(new URL('../src/client/public-suffix.mjs', import.meta.url));
const OUT_TLDS = fileURLToPath(new URL('../src/client/top-level-domains.mjs', import.meta.url));

/** The header both generated files carry: what they are and the list's licence. @param {string} what */
const header = (what) => `// @ts-check
/**
 * @file ${what} Generated by scripts/update-psl.mjs; do not edit.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at https://mozilla.org/MPL/2.0/.`;

/**
 * The top-level endings ("com", "ge", "გე"): the ICANN rules of one label,
 * and the endings that only appear under a wildcard ("*.ck").
 * @param {string[]} icann
 */
export function topLevel(icann) {
  const endings = new Set();
  for (const rule of icann) {
    const bare = rule.replace(/^[!*]\.?/, '');
    if (!bare.includes('.')) endings.add(bare);
  }
  return [...endings].sort();
}

/**
 * The rules of one section, compacted: one line per top-level ending,
 * "ending:rest,rest,…", where each rest is the part of a rule before that
 * ending ("com.ge" is "ge:com"). A rule that is only the ending has an empty
 * rest. "*" and "!" keep their meaning from the list.
 * @param {string[]} rules
 */
export function compact(rules) {
  /** @type {Map<string, string[]>} */
  const byEnding = new Map();
  for (const rule of rules) {
    const at = rule.lastIndexOf('.');
    const ending = rule.slice(at + 1);
    const rest = at === -1 ? '' : rule.slice(0, at);
    const list = byEnding.get(ending) ?? [];
    list.push(rest);
    byEnding.set(ending, list);
  }
  return [...byEnding].map(([ending, rests]) => `${ending}:${rests.join(',')}`).join('\n');
}

/**
 * Splits the list into its two sections, keeping rules in list order.
 * @param {string} text
 */
export function sections(text) {
  /** @type {{ icann: string[], private: string[] }} */
  const out = { icann: [], private: [] };
  /** @type {'icann' | 'private' | null} */
  let section = null;
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (line.startsWith('// ===BEGIN ICANN')) section = 'icann';
    else if (line.startsWith('// ===BEGIN PRIVATE')) section = 'private';
    else if (line.startsWith('// ===END')) section = null;
    else if (section && line && !line.startsWith('//')) out[section].push(line.split(/\s/)[0].toLowerCase());
  }
  if (out.icann.length < 5000 || out.private.length < 1000) throw new Error(`The list looks truncated (${out.icann.length} ICANN, ${out.private.length} private rules); check the download from ${SOURCE}.`);
  return out;
}

async function main() {
  const local = process.argv[2];
  const text = local ? await readFile(local, 'utf8') : await (await fetch(SOURCE)).text();
  const { icann, private: shared } = sections(text);
  const today = new Date().toISOString().slice(0, 10);
  const source = `${header('The Public Suffix List (https://publicsuffix.org/), compacted.')}
 *
 * Format: one line per top-level ending, "ending:rest,rest,…"; a rule is
 * "rest.ending", or the ending alone for an empty rest. ICANN holds the
 * endings run by registries; SHARED the names under which a company lets
 * anyone make their own (the list's "private" section).
 */

/** The date the list was downloaded. */
export const UPDATED = '${today}';

export const ICANN = ${JSON.stringify(compact(icann))};

export const SHARED = ${JSON.stringify(compact(shared))};
`;
  await writeFile(OUT, source);
  console.log(`Wrote ${OUT}: ${icann.length} ICANN and ${shared.length} private rules, ${source.length} bytes.`);

  const endings = topLevel(icann);
  const tlds = `${header('The top-level endings of the Public Suffix List (https://publicsuffix.org/), comma-separated.')}
 */

export const TLDS = ${JSON.stringify(endings.join(','))};
`;
  await writeFile(OUT_TLDS, tlds);
  console.log(`Wrote ${OUT_TLDS}: ${endings.length} endings, ${tlds.length} bytes.`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`Could not update the Public Suffix List: ${error instanceof Error ? error.message : error}`);
    process.exit(1);
  });
}
